#!/usr/bin/env python3
"""Paid Task Engine 2.3 upgrade. Run --self-test, then --apply in the engine folder.
Only upgrades discovery. Does not enable auto-delivery, spend money, contact buyers,
change credentials, reset allowances, or touch other Docker services.
Upload this file to GitHub using your browser; no secrets are embedded.
"""
import argparse,base64,hashlib,json,os,shutil,sqlite3,subprocess,sys,tempfile,zlib
from datetime import datetime,timezone
from pathlib import Path
PAYLOAD=''
BASE_HASH='a875d28e997932ad394f934f6d8512f559a3872fd7bcea6231d7a00233227f00'
FILES=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))

def tests():
 with tempfile.TemporaryDirectory() as tmp:
  root=Path(tmp)
  for name,content in FILES.items():
   p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
  subprocess.run([sys.executable,'-m','unittest','discover','-s',str(root/'tests'),'-q'],check=True)

def apply(target):
 target=target.resolve()
 for name in ('engine.py','config.json','compose.yaml','.env'):
  if not (target/name).is_file():raise SystemExit('Missing '+name+'. Run from ~/paid-task-engine.')
 current=(target/'engine.py').read_bytes()
 newhash=hashlib.sha256(FILES['engine.py'].encode()).hexdigest()
 oldhash=hashlib.sha256(current).hexdigest()
 if oldhash==newhash:
  print('Version 2.3 source is already installed. Rebuild the paid-task-engine service if needed.');return
 if oldhash!=BASE_HASH:raise SystemExit('engine.py differs from the supplied v2.2 baseline. Nothing changed; preserve your custom changes before upgrading.')
 cfg=json.loads((target/'config.json').read_text())
 # Preserve all existing configuration, including custom discovery lanes.
 compile(FILES['engine.py'],'engine.py','exec')
 # Read only the engine database in its own container; never inspect other services.
 check="import sqlite3,os; c=sqlite3.connect('file:'+os.environ.get('DATA_DIR','/data')+'/engine.sqlite?mode=ro',uri=True); print(c.execute(\"SELECT COUNT(*) FROM runs WHERE state='running'\").fetchone()[0])"
 result=subprocess.run(['docker','compose','exec','-T','paid-task-engine','python','-c',check],cwd=target,capture_output=True,text=True)
 if result.returncode or result.stdout.strip()!='0':
  raise SystemExit('Cannot confirm engine is idle. Wait for current runs to finish and ensure the engine is running. Nothing changed.')
 tag=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
 backup=target/('backup-before-v23-'+tag);backup.mkdir(mode=0o700)
 for name in ('engine.py','config.json'):
  shutil.copy2(target/name,backup/name)
 # SQLite online backup preserves old history while writing a consistent snapshot.
 dbbackup="from pathlib import Path; import sqlite3,os; d=Path(os.environ.get('DATA_DIR','/data')); (d/'backups').mkdir(exist_ok=True); s=sqlite3.connect(d/'engine.sqlite'); t=sqlite3.connect(d/'backups'/'pre-v23-"+tag+".sqlite'); s.backup(t); t.close(); s.close()"
 subprocess.run(['docker','compose','exec','-T','paid-task-engine','python','-c',dbbackup],cwd=target,check=True)
 changes={'engine.py':FILES['engine.py'],'config.json':json.dumps(cfg,indent=2)+'\n','inspect_discovery.py':FILES['inspect_discovery.py']}
 try:
  for name,content in changes.items():
   staging=target/(name+'.v23-tmp');staging.write_text(content);os.replace(staging,target/name)
 except Exception:
  for name in ('engine.py','config.json'):shutil.copy2(backup/name,target/name)
  raise
 print('Upgrade files installed. Credentials and spending limits preserved.')
 print('Backup:',backup)
 print('Rebuild only this service: docker compose up -d --build paid-task-engine')
 print('Check: python3 ctl.py health (expect version 2.3.0)')
 print('Inspect findings: python3 inspect_discovery.py')
 print('Inspect searches: python3 inspect_discovery.py --audit')
 print('Rollback files: cp '+str(backup/'engine.py')+' '+str(target/'engine.py'))
 print('               cp '+str(backup/'config.json')+' '+str(target/'config.json'))
 print('Then rebuild the same service. Do not delete the data volume.')

if __name__=='__main__':
 p=argparse.ArgumentParser(description=__doc__)
 group=p.add_mutually_exclusive_group(required=True)
 group.add_argument('--self-test',action='store_true')
 group.add_argument('--apply',action='store_true')
 p.add_argument('--target',default='.')
 args=p.parse_args()
 if args.self_test:tests()
 else:apply(Path(args.target))
